const domain=(n,ta,a=null)=>(a!==null&&a<18&&((ta?MINOR_DOMAINS_TA:MINOR_DOMAINS_EN)[n])?(ta?MINOR_DOMAINS_TA:MINOR_DOMAINS_EN)[n]:(ta?DOMAINS_TA:DOMAINS_EN)[n-1]);
